css:
@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;700&family=Noto+Naskh+Arabic:wght@400;700&family=Ubuntu:wght@400;700&display=swap');
@page { size: A4; margin: 10mm; }
body { margin: 0; padding: 0; color: #333; }
.page { width: 190mm; margin: 0 auto; page-break-after: always; }
.header { border-bottom: 2px solid #07417b; padding: 10px 0; display: table; width: 100%; }
.header .logo-cell { display: table-cell; width: 25%; vertical-align: middle; }
.header .logo-cell img { max-width: 110px; }
.header .name-cell { display: table-cell; width: 75%; vertical-align: middle; text-align: right; }
.title-en { text-align: center; font-weight: bold; margin: 20px 0 10px; }
.title-ar { text-align: center; font-family: 'Noto Naskh Arabic', serif; font-weight: 700; margin: 5px 0 20px; direction: rtl; }
.section { margin: 15px 0; }
.section h3 { border-bottom: 1px solid #ccc; padding-bottom: 5px; }
.bilingual { display: table; width: 100%; }
.bilingual .left { display: table-cell; width: 50%; text-align: left; vertical-align: top; }
.bilingual .right { display: table-cell; width: 50%; text-align: right; direction: rtl; vertical-align: top; }
table.passengers { width: 100%; border-collapse: collapse; margin: 10px 0; }
table.passengers th { background: #07417b; color: #fff; padding: 6px 8px; text-align: left; }
table.passengers th.ar-th { text-align: right; direction: rtl; }
table.passengers td { padding: 6px 8px; border-bottom: 1px solid #eee; }
table.passengers tr:nth-child(even) { background: #f9fafb; }
.tc { direction: rtl; text-align: right; line-height: 2; }
.tc h3 { font-family: 'Noto Naskh Arabic', serif; }
.signature-area { margin-top: 40px; display: table; width: 100%; }
.signature-area .party { display: table-cell; width: 45%; vertical-align: top; text-align: center; }
.signature-area .party .line { border-top: 1px solid #333; width: 80%; margin: 40px auto 5px; padding-top: 5px; }
.footer { text-align: center; margin-top: 20px; border-top: 1px solid #ccc; padding-top: 10px; font-size: 9pt; color: #666; }

html:
{% set company_doc = frappe.get_doc('Company', doc.company) %}
{% set company_en = company_doc.company_name or doc.company %}
{% set company_ar = company_doc.company_name_arabic or company_en %}
{% set company_email = company_doc.email or '' %}
{% set company_phone = company_doc.phone_no or company_doc.phone or '' %}
{% set reg_no = company_doc.registration_details or company_doc.cr_no or '' %}
{% set gregorian = frappe.utils.formatdate(doc.trip_date, 'dd-MM-yyyy') if doc.trip_date else '' %}
{% set first = doc.passengers[0] if doc.passengers else None %}

<style>
  @page { size: A4; margin: 0; }
  body { margin: 0; }
  .sheet { padding: 150px 45px 95px 45px; color: #111; font-family: 'Ubuntu', 'Amiri', sans-serif; font-size: 11pt; }
  .hdr { position: fixed; top: 0; left: 0; right: 0; height: 120px; padding: 14px 45px 0 45px; background: #fff; border-bottom: 2px solid #07417b; display: flex; align-items: center; justify-content: space-between; }
  .hdr .qr { width: 33%; }
  .hdr .qr img { width: 92px; height: 92px; }
  .hdr .brand { width: 67%; text-align: right; }
  .hdr .brand img { height: 56px; display: block; margin: 0 0 4px auto; }
  .hdr .en { font-size: 15pt; font-weight: 700; color: #07417b; margin: 0; }
  .hdr .ar { font-family: 'Amiri', 'Noto Naskh Arabic', serif; font-size: 18pt; font-weight: 700; color: #07417b; margin: 0; direction: rtl; }
  .ftr { position: fixed; bottom: 0; left: 0; right: 0; height: 70px; padding: 0 45px; border-top: 1px solid #ccc; display: flex; align-items: center; justify-content: space-between; font-size: 10pt; color: #333; background: #fff; }
  .ftr .ar { direction: rtl; font-family: 'Amiri', serif; font-size: 11pt; }
  .title-en { text-align: center; font-size: 20pt; font-weight: 700; color: #07417b; margin: 6px 0 0 0; }
  .title-ar { text-align: center; font-family: 'Amiri', 'Noto Naskh Arabic', serif; font-size: 24pt; font-weight: 700; color: #07417b; margin: 2px 0 14px 0; direction: rtl; }
  h3 { color: #07417b; font-size: 12pt; border-bottom: 1px solid #ccc; padding-bottom: 3px; margin: 16px 0 8px 0; }
  table.plist { width: 100%; border-collapse: collapse; font-size: 10pt; }
  table.plist th { background: #07417b; color: #fff; padding: 6px; text-align: left; }
  table.plist td { padding: 6px; border-bottom: 1px solid #e5e5e5; }
  .page2 { page-break-before: always; direction: rtl; font-family: 'Amiri', 'Noto Naskh Arabic', serif; font-size: 13pt; line-height: 2; text-align: right; }
  .page2 h3 { font-family: 'Amiri', serif; font-size: 15pt; text-align: center; border: none; }
  .page2 ul { padding-right: 22px; }
  .sign { display: flex; justify-content: space-between; margin-top: 50px; font-size: 12pt; }
  .sign div { width: 45%; border-top: 1px solid #333; padding-top: 6px; text-align: center; }
</style>

<div class="hdr">
  <div class="qr">
    {% if doc.qr_code %}<img src="{{ doc.qr_code }}" alt="QR">{% endif %}
  </div>
  <div class="brand">
    {% if company_doc.company_logo %}<img src="{{ company_doc.company_logo | abs_url }}" alt="Logo">{% endif %}
    <p class="en">{{ company_en }}</p>
    <p class="ar">{{ company_ar }}</p>
  </div>
</div>

<div class="ftr">
  <div>{{ company_email }}</div>
  <div class="ar">{{ company_phone }}{% if reg_no %} | {{ reg_no }}{% endif %}</div>
</div>

<div class="sheet">
  <div class="title-en">Trip Contract</div>
  <div class="title-ar">عقد نقل ركاب</div>

  <h3>Contract Details / تفاصيل العقد</h3>
  <p><strong>Contract No:</strong> {{ doc.name }} &nbsp;&nbsp; <strong>Date:</strong> {{ gregorian }} &nbsp;&nbsp; <strong>Hijri:</strong> {{ doc.hijri_date or '' }}</p>
  <p><strong>From:</strong> {{ doc.from_location or '' }} &nbsp;&nbsp; <strong>To:</strong> {{ doc.to_location or '' }}</p>
  <p><strong>Status:</strong> {{ doc.trip_status or 'Draft' }}</p>

  <h3>Passenger List / قائمة الركاب</h3>
  <table class="plist">
    <thead>
      <tr><th style="width:6%">#</th><th>Name / الاسم</th><th style="width:20%">Nationality / الجنسية</th><th style="width:22%">Document / الوثيقة</th></tr>
    </thead>
    <tbody>
      {% for p in doc.passengers %}
      <tr>
        <td>{{ loop.index }}</td>
        <td>{{ p.passenger_name or '' }}</td>
        <td>{{ p.nationality or '' }}</td>
        <td>{{ p.document_number or '' }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
</div>

<div class="page2 sheet" style="padding-top: 150px;">
  <h3>عقد نقل ركاب بالحافلات</h3>
  <p>{{ gregorian }} م &nbsp;|&nbsp; {{ doc.hijri_date or '' }} هـ</p>
  <p>تم إبرام هذا العقد بين:</p>
  <p><strong>الطرف الأول:</strong> {{ company_ar }}</p>
  <p><strong>الطرف الثاني:</strong> {% if first and first.passenger_name %}{{ first.passenger_name }}{% else %}____________{% endif %}</p>

  <h3>بناءً على:</h3>
  <p>المادة (39) من اللائحة المنظمة لنشاط النقل البري للركاب وتوجيه الحافلات.</p>
  <p>المادة (1) من المادة (39) التي تنص على وجوب إبرام الناقل لعقد نقل مع الأطراف التجارية الأخرى.</p>

  <h3>اتفق الطرفان على ما يلي:</h3>
  <p><strong>موضوع العقد:</strong></p>
  <ul>
    <li>يتعهد الطرف الأول بتنفيذ عملية نقل للطرف الثاني، مع مراقبة وتوجيه الركاب من الموقع المحدد مسبقًا، وتوصيلهم إلى الوجهة المحددة في هذا العقد.</li>
  </ul>
  <p><strong>نقطة الانطلاق:</strong> {{ doc.from_location or '' }}<br><strong>نقطة الوصول:</strong> {{ doc.to_location or '' }}</p>

  <div class="sign">
    <div>توقيع الطرف الأول</div>
    <div>توقيع الطرف الثاني</div>
  </div>
</div>
